import React, { useState, useEffect } from 'react';
import SearchForm from './SearchForm';
import ImageLogSearchForm from './ImageLogSearchForm';
import AdvancedSearchForm from './AdvancedSearchForm';
import LogTable from './LogTable';
import ImageLogTable from './ImageLogTable';
import './LogGrid.css';

const LogGrid = ({ logType }) => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [currentPage, setCurrentPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [sortField, setSortField] = useState('log_timestamp');
  const [sortDirection, setSortDirection] = useState('desc');

  // 검색 조건 상태
  const [searchParams, setSearchParams] = useState({
    startDate: '',
    endDate: '',
    mediaCode: '',
    trCode: '',
    loginId: '',
    accountNumbers: []
  });

  // 로그 타입에 따라 기본 정렬 필드 설정 (초기화 시 한 번만)
  useEffect(() => {
    if (!logType) return;

    if (logType.id === 'java_fw_imglog' && sortField === 'log_timestamp') {
      setSortField('insert_time');
    } else if (logType.id === 'pb_feplog' && sortField === 'insert_time') {
      setSortField('log_timestamp');
    }
  }, [logType?.id]); // logType.id가 변경될 때만 실행

  // logType이 없으면 null 반환
  if (!logType) {
    return null;
  }

  // 검색 실행 함수
  const handleSearch = async (params) => {
    console.log('🔍 프론트엔드에서 받은 파라미터:', params);
    setLoading(true);
    setSearchParams(params);

    try {
      const requestData = {
        ...params,
        logType: logType.id, // 로그 타입 추가
        page: currentPage,
        pageSize: 10,
        sortField: sortField,
        sortDirection: sortDirection,
        displayTemplate: 'detailed'
      };
      console.log('📤 API로 전송할 데이터:', requestData);

      // 실제 API 호출
      const apiBaseUrl = process.env.REACT_APP_API_BASE_URL || 'http://localhost:9200/api';
      const response = await fetch(`${apiBaseUrl}/logs/db-refactored/search`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(requestData)
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      console.log('📥 API 응답:', result);

      if (result.success) {
        const logData = result.data?.data || result.data || [];
        console.log('✅ 검색 성공:', logData.length, '건');
        setLogs(logData);
        setTotalPages(result.data?.pagination?.totalPages || result.pagination?.totalPages || 1);
        setCurrentPage(result.data?.pagination?.currentPage || result.pagination?.currentPage || 1);
      } else {
        console.error('❌ API 오류:', result.error);
      }
    } catch (error) {
      console.error('검색 중 오류 발생:', error);
    } finally {
      setLoading(false);
    }
  };

  // 정렬 처리
  const handleSort = async (field) => {
    let newSortDirection = 'asc';

    if (sortField === field) {
      newSortDirection = sortDirection === 'asc' ? 'desc' : 'asc';
    }

    setSortField(field);
    setSortDirection(newSortDirection);

    // 현재 검색 조건으로 API 재호출
    if (Object.keys(searchParams).length > 0) {
      try {
        const apiBaseUrl = process.env.REACT_APP_API_BASE_URL || 'http://localhost:9200/api';
        const response = await fetch(`${apiBaseUrl}/logs/db-refactored/search`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
        body: JSON.stringify({
          ...searchParams,
          logType: logType.id, // 로그 타입 추가
          page: currentPage,
          pageSize: 10,
          sortField: field,
          sortDirection: newSortDirection,
          displayTemplate: 'detailed'
        })
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const result = await response.json();

        if (result.success) {
          const logData = result.data?.data || result.data || [];
          setLogs(logData);
          setTotalPages(result.data?.pagination?.totalPages || result.pagination?.totalPages || 1);
        } else {
          console.error('API 오류:', result.error);
        }
      } catch (error) {
        console.error('정렬 중 오류 발생:', error);
      }
    }
  };

  // 페이지 변경
  const handlePageChange = async (page) => {
    setCurrentPage(page);

    // 현재 검색 조건으로 API 재호출
    if (Object.keys(searchParams).length > 0) {
      try {
        const apiBaseUrl = process.env.REACT_APP_API_BASE_URL || 'http://localhost:9200/api';
        const response = await fetch(`${apiBaseUrl}/logs/db-refactored/search`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
        body: JSON.stringify({
          ...searchParams,
          logType: logType.id, // 로그 타입 추가
          page: page,
          pageSize: 10,
          sortField: sortField,
          sortDirection: sortDirection,
          displayTemplate: 'detailed'
        })
        });

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const result = await response.json();

        if (result.success) {
          const logData = result.data?.data || result.data || [];
          setLogs(logData);
          setTotalPages(result.data?.pagination?.totalPages || result.pagination?.totalPages || 1);
        } else {
          console.error('API 오류:', result.error);
        }
      } catch (error) {
        console.error('페이지 변경 중 오류 발생:', error);
      }
    }
  };



  const isImageLog = logType && logType.id === 'java_fw_imglog';
  const useAdvancedSearch = isImageLog; // imagelog만 고급 검색 사용

  // 고급 검색 처리
  const handleAdvancedSearch = async (searchRequest) => {
    setLoading(true);
    setSearchParams({});
    setCurrentPage(1);

    try {
      const apiBaseUrl = process.env.REACT_APP_API_BASE_URL || 'http://localhost:9200/api';
      const response = await fetch(`${apiBaseUrl}/logs/db-refactored/advanced-search`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(searchRequest)
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const result = await response.json();
      console.log('📥 고급 검색 API 응답:', result);

      if (result.success) {
        const logData = result.data?.data || result.data || [];
        console.log('✅ 검색 성공:', logData.length, '건');
        setLogs(logData);
        setTotalPages(result.data?.pagination?.totalPages || result.pagination?.totalPages || 1);
        setCurrentPage(result.data?.pagination?.currentPage || result.pagination?.currentPage || 1);
      } else {
        console.error('❌ API 오류:', result.error);
      }
    } catch (error) {
      console.error('검색 중 오류 발생:', error);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="log-grid">
      <div className="log-grid-header">
        <h2>{logType?.name || '로그 검색'}</h2>
        <p className="log-type-description">{logType?.description || ''}</p>
      </div>
      {useAdvancedSearch ? (
        <AdvancedSearchForm logType={logType} onSearch={handleAdvancedSearch} />
      ) : isImageLog ? (
        <ImageLogSearchForm onSearch={handleSearch} />
      ) : (
        <SearchForm onSearch={handleSearch} />
      )}
      {isImageLog ? (
        <ImageLogTable
          logs={logs}
          loading={loading}
          sortField={sortField}
          sortDirection={sortDirection}
          onSort={handleSort}
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={handlePageChange}
          keywords={searchParams.keywords || []}
        />
      ) : (
        <LogTable 
          logs={logs}
          loading={loading}
          sortField={sortField}
          sortDirection={sortDirection}
          onSort={handleSort}
          currentPage={currentPage}
          totalPages={totalPages}
          onPageChange={handlePageChange}
          keywords={searchParams.keywords || []}
        />
      )}
    </div>
  );
};

export default LogGrid;
